{
  "apiVersion": 1,
  "type": "help",
  "data": {
    "command": "astryx template",
    "description": "List, show, or scaffold page and block templates",
    "usage": "astryx template [options] [name] [path]",
    "options": [
      {
        "flags": "--list",
        "description": "List available templates (narrow with --type and --package) and do nothing else: <name>, <path>, --skeleton and --overwrite are refused"
      },
      {
        "flags": "--type <type>",
        "description": "Filter by template type: page or block"
      },
      {
        "flags": "--package <pkg>",
        "description": "Narrow to templates from a specific package. Use @astryxdesign/core to select an original hidden by an integration replacement."
      },
      {
        "flags": "--skeleton",
        "description": "Show layout skeleton with spatial annotations (padding, gap, nesting) instead of the source. Needs <name>. It writes nothing, so <path> and --overwrite are refused with ERR_INVALID_ARGUMENT"
      },
      {
        "flags": "--cdn [path]",
        "description": "Write the no-build-step CDN starter page and do nothing else: <name>, --list, --skeleton, --type and --package are refused. The page goes to the --cdn value, else to <path>, else cdn.template.html, and that path is always the file itself. A value right after --cdn (anything not starting with -) is taken as that path"
      },
      {
        "flags": "-f, --overwrite",
        "description": "Replace an existing target file. Without it an existing file is refused (ERR_FILE_EXISTS) and an existing CDN page is left as is"
      }
    ],
    "subcommands": []
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
